/*
 * headless_editmenu_verbs.c - Editmenu processor verbs
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py.
 * Now contains intentional no-ops for headless compatibility (not interim stubs).
 * All verbs return true (silently skipped) since edit operations require a GUI.
 * Do not replace with "real" implementations without considering this behavioral
 * contract — scripts like userland.cleanRoot depend on these succeeding silently.
 */

#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"

/* Token enum for all verbs in the editmenu processor */
enum {
    ediv_undo = 0,
    ediv_cut = 1,
    ediv_copy = 2,
    ediv_paste = 3,
    ediv_clear = 4,
    ediv_selectall = 5,
    ediv_getfont = 6,
    ediv_getfontsize = 7,
    ediv_setfont = 8,
    ediv_setfontsize = 9,
    ediv_plaintext = 10,
    ediv_setbold = 11,
    ediv_setitalic = 12,
    ediv_setunderline = 13,
    ediv_setoutline = 14,
    ediv_setshadow = 15
};

static boolean editmenu_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    (void)hparam1;
    (void)bserror;
    /* Headless: all edit menu verbs are GUI no-ops. Return true
     * (operation silently skipped) so scripts like userland.cleanRoot
     * that use clipboard/edit operations don't error out. */
    switch(token) {
        case ediv_getfont:
            /* Headless: return empty string (callers expect font name) */
            return setstringvalue(emptystring, vreturned);
        case ediv_getfontsize:
            /* Headless: return 0 (callers expect numeric size) */
            return setlongvalue(0, vreturned);
        case ediv_undo:
        case ediv_cut:
        case ediv_copy:
        case ediv_paste:
        case ediv_clear:
        case ediv_selectall:
        case ediv_setfont:
        case ediv_setfontsize:
        case ediv_plaintext:
        case ediv_setbold:
        case ediv_setitalic:
        case ediv_setunderline:
        case ediv_setoutline:
        case ediv_setshadow:
            return setbooleanvalue(true, vreturned);
        default:
            return false;
    }
}

boolean editmenuinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(PSTRING("\010", "editmenu"), bsname);

    if (!newfunctionprocessor(bsname, &editmenu_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(PSTRING("\004", "undo"), ediv_undo);
    ADD_VERB(PSTRING("\003", "cut"), ediv_cut);
    ADD_VERB(PSTRING("\004", "copy"), ediv_copy);
    ADD_VERB(PSTRING("\005", "paste"), ediv_paste);
    ADD_VERB(PSTRING("\005", "clear"), ediv_clear);
    ADD_VERB(PSTRING("\011", "selectall"), ediv_selectall);
    ADD_VERB(PSTRING("\007", "getfont"), ediv_getfont);
    ADD_VERB(PSTRING("\013", "getfontsize"), ediv_getfontsize);
    ADD_VERB(PSTRING("\007", "setfont"), ediv_setfont);
    ADD_VERB(PSTRING("\013", "setfontsize"), ediv_setfontsize);
    ADD_VERB(PSTRING("\011", "plaintext"), ediv_plaintext);
    ADD_VERB(PSTRING("\007", "setbold"), ediv_setbold);
    ADD_VERB(PSTRING("\011", "setitalic"), ediv_setitalic);
    ADD_VERB(PSTRING("\014", "setunderline"), ediv_setunderline);
    ADD_VERB(PSTRING("\012", "setoutline"), ediv_setoutline);
    ADD_VERB(PSTRING("\011", "setshadow"), ediv_setshadow);

    #undef ADD_VERB

    pophashtable();
    return true;
}
